import{_ as s,o as a,c as t,ah as n}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Candidatures","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/secretariat/candidatures.md","filePath":"src/guide/secretariat/candidatures.md"}'),r={name:"guide/secretariat/candidatures.md"};function i(o,e,l,u,d,c){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="candidatures" tabindex="-1">Candidatures <a class="header-anchor" href="#candidatures" aria-label="Permalink to &quot;Candidatures&quot;">​</a></h1><p>La page <strong>Dossiers à traiter</strong> liste toutes les candidatures déposées pour une inscription, qu&#39;elles viennent du formulaire public rempli par une famille (canal <strong>En ligne</strong>) ou d&#39;une saisie faite par la caisse pour une famille venue sur site (canal <strong>Caisse</strong>). C&#39;est depuis cette page que vous décidez d&#39;accepter ou de refuser chaque dossier.</p><p>Les familles accèdent au formulaire public par le bouton <strong>Inscrire mon enfant</strong> de la page d&#39;accueil de l&#39;établissement.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Consulter la file d&#39;attente est toujours disponible. L&#39;affectation à une classe (la validation d&#39;un dossier) dépend du module Admissions activé pour votre établissement — si le bouton <strong>Valider</strong> n&#39;apparaît pas, contactez votre administrateur.</p></div><h2 id="consulter-la-file-d-attente" tabindex="-1">Consulter la file d&#39;attente <a class="header-anchor" href="#consulter-la-file-d-attente" aria-label="Permalink to &quot;Consulter la file d&#39;attente&quot;">​</a></h2><p>La page affiche pour chaque dossier le nom de l&#39;élève, le site souhaité, le département souhaité, le canal et le statut :</p><table tabindex="0"><thead><tr><th>Statut</th><th>Signification</th></tr></thead><tbody><tr><td>En attente</td><td>Le dossier n&#39;a pas encore été traité</td></tr><tr><td>Validé</td><td>L&#39;élève a été affecté à une classe</td></tr><tr><td>Refusé</td><td>Le dossier a été refusé, avec un motif consigné</td></tr></tbody></table><p>Utilisez le champ de recherche pour retrouver un dossier par nom, et le filtre de statut pour n&#39;afficher que les dossiers en attente, validés ou refusés. Cliquez sur <strong>Examiner</strong> sur la ligne d&#39;un dossier pour l&#39;ouvrir.</p><h2 id="examiner-un-dossier" tabindex="-1">Examiner un dossier <a class="header-anchor" href="#examiner-un-dossier" aria-label="Permalink to &quot;Examiner un dossier&quot;">​</a></h2><p>La page de détail d&#39;un dossier vous montre :</p><ul><li>la <strong>date de naissance</strong> de l&#39;élève, le <strong>site</strong> et le <strong>département</strong> souhaités, et le <strong>canal</strong> (En ligne ou Caisse) ;</li><li>si le dossier a été saisi par la caisse, le nom de la personne qui l&#39;a <strong>saisi</strong> ;</li><li>la liste des <strong>parents / tuteurs</strong> avec leur nom, e-mail, téléphone et lien de parenté ; le contact principal porte une étiquette <strong>Contact principal</strong> ;</li><li>la liste des <strong>documents</strong> joints au dossier, avec qui les a ajoutés (un membre de l&#39;équipe, ou <strong>Soumis en ligne</strong> si la famille les a déposés elle-même via le formulaire public) — cliquez sur <strong>Télécharger</strong> pour ouvrir un document.</li></ul><p>Si aucun document n&#39;a été joint, la page l&#39;indique clairement.</p><h2 id="valider-un-dossier" tabindex="-1">Valider un dossier <a class="header-anchor" href="#valider-un-dossier" aria-label="Permalink to &quot;Valider un dossier&quot;">​</a></h2><ol><li>Ouvrez le dossier depuis <strong>Examiner</strong>.</li><li>Dans le bloc <strong>Affecter à une classe</strong>, choisissez la <strong>classe</strong> dans la liste. Chaque classe affiche son année scolaire et son occupation actuelle (par exemple <code>24/30</code>, ou <code>∞</code> si elle n&#39;a pas de capacité maximale définie). Les classes de l&#39;année suivante, si elle est déjà préparée, sont proposées aussi : un dossier validé en juin peut entrer directement dans la classe de la rentrée.</li><li>Si la classe a atteint sa capacité, vous ne pouvez pas la sélectionner normalement : cochez <strong>Forcer l&#39;affectation même si la classe a atteint sa capacité</strong> pour l&#39;assigner malgré tout.</li><li>Cliquez sur <strong>Valider</strong>.</li></ol><p>L&#39;élève est alors inscrit dans la classe choisie, pour l&#39;année de cette classe, et son dossier financier devient visible pour la caisse dans <strong>Facturation</strong> — voir <a href="/era-guide/guide/caissier/inscriptions-et-paiements.html">Inscriptions et paiements</a>.</p><h3 id="un-eleve-deja-connu" tabindex="-1">Un élève déjà connu <a class="header-anchor" href="#un-eleve-deja-connu" aria-label="Permalink to &quot;Un élève déjà connu&quot;">​</a></h3><p>Si ERA connaît déjà un élève avec les mêmes prénom, nom et date de naissance (un ancien élève qui revient, par exemple), le bloc <strong>Affecter à une classe</strong> l&#39;indique avec sa dernière classe. La validation inscrit alors cet élève existant, sans créer de second dossier : son historique reste au même endroit. S&#39;il est déjà inscrit pour l&#39;année de la classe choisie, la validation est refusée. Ses matières de spécialité sont reprises si la nouvelle classe les propose toujours au choix.</p><h3 id="les-comptes-des-parents" tabindex="-1">Les comptes des parents <a class="header-anchor" href="#les-comptes-des-parents" aria-label="Permalink to &quot;Les comptes des parents&quot;">​</a></h3><p>À la validation, chaque parent du dossier reçoit un compte ERA, identifié par son adresse e-mail (majuscules et minuscules ne comptent pas). Un parent qui a déjà un compte avec cette adresse, pour un autre enfant par exemple, le garde : l&#39;enfant s&#39;y ajoute, sans nouvel e-mail.</p><p>Si un compte parent existe déjà <strong>au même nom mais avec une autre adresse</strong>, le bloc <strong>Affecter à une classe</strong> le signale, avec les enfants rattachés à ce compte. Choisissez alors :</p><ul><li><strong>Créer un compte avec …</strong> (choix par défaut) : c&#39;est un homonyme, ou le parent veut un compte séparé ;</li><li><strong>Rattacher l&#39;enfant au compte existant …</strong> : c&#39;est le même parent. Il retrouve tous ses enfants dans le même espace, sans second compte.</li></ul><p>En cas de doute, vérifiez auprès de la famille avant de valider.</p><h2 id="refuser-un-dossier" tabindex="-1">Refuser un dossier <a class="header-anchor" href="#refuser-un-dossier" aria-label="Permalink to &quot;Refuser un dossier&quot;">​</a></h2><ol><li>Ouvrez le dossier depuis <strong>Examiner</strong>.</li><li>Cliquez sur <strong>Refuser</strong>.</li><li>Dans la fenêtre de confirmation, indiquez le <strong>Motif de refus</strong> (ce champ est obligatoire).</li><li>Confirmez en cliquant à nouveau sur <strong>Refuser</strong>.</li></ol><p>Le motif de refus reste consigné sur le dossier et reste consultable par la suite.</p>',25)])])}const g=s(r,[["render",i]]);export{m as __pageData,g as default};
